struct Task {
    title: String,
    done: bool,
}

struct List {
    tasks: Vec<Task>,
}

impl List {
    fn add(&mut self, title: String) {}
}

fn main() {
    let mut list = List { tasks: Vec::new() };
    let title = String::from("write report");
    list.add(title);
